use vstd::prelude::*;

verus! {
    // Specification for checking if all elements in the array are less than the threshold
    spec fn all_less_than_threshold(l: Vec<i8>, t: i8) -> bool
        decreases l.len(),
    {
        if l.len() == 0 {
            true
        } else {
            l[0] < t && all_less_than_threshold(l[1..].to_vec(), t)
        }
    }

    // Function to check if all elements in the array are strictly less than the threshold
    fn check_below_threshold(l: Vec<i8>, t: i8) -> (result: bool)
        ensures
            result == all_less_than_threshold(l, t),
    {
        if l.len() == 0 {
            return true; // An empty array satisfies the condition
        }

        let mut idx: usize = 0;
        let mut result: bool = true;

        while idx < l.len()
            invariant
                idx <= l.len(),
                result == all_less_than_threshold(l[0..idx].to_vec(), t),
                all_less_than_threshold(l, t),
            decreases l.len() - idx,
        {
            if l[idx] >= t {
                result = false; // Found an element that is not less than the threshold
                break; // Exit the loop early
            }
            idx = idx + 1;
        }

        result
    }
}

